package io.github.sidd065.agentcompanion.core

import io.github.sidd065.agentcompanion.net.Noise
import io.github.sidd065.agentcompanion.net.SecureSocket
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/** Byte-exact interop with the daemon's Noise (vectors generated by its Go tests). */
class NoiseTest {
    private fun hex(s: String): ByteArray = ByteArray(s.length / 2) { i -> s.substring(2 * i, 2 * i + 2).toInt(16).toByte() }

    private val vectors = Json.parseToJsonElement(javaClass.classLoader!!.getResource("noise-vectors.json")!!.readText()).jsonArray

    @Test fun matchesDaemonVectors() {
        assertEquals(2, vectors.size)
        for (v in vectors) {
            val o = v.jsonObject
            fun f(k: String) = hex(o[k]!!.jsonPrimitive.content)
            val s = Noise.KeyPair(f("initStaticPriv"), Noise.publicFromPrivate(f("initStaticPriv")))
            val e = Noise.KeyPair(f("initEphemeralPriv"), Noise.publicFromPrivate(f("initEphemeralPriv")))
            val psk = o["psk"]?.let { hex(it.jsonPrimitive.content) }
            val ini = Noise.Initiator(s, f("respStaticPub"), f("prologue"), psk, ephemeral = e)
            val name = o["name"]!!.jsonPrimitive.content
            assertArrayEquals("$name msg1", f("msg1"), ini.writeMessage1(f("msg1Payload")))
            val sess = ini.readMessage2(f("msg2"))
            assertArrayEquals("$name msg2 payload", f("msg2Payload"), sess.responderPayload)
            assertArrayEquals("$name handshake hash", f("handshakeHash"), sess.handshakeHash)
            for (t in o["transport"]!!.jsonArray) {
                val tt = t.jsonObject
                val plain = hex(tt["plain"]!!.jsonPrimitive.content)
                val cipher = hex(tt["cipher"]!!.jsonPrimitive.content)
                if (tt["dir"]!!.jsonPrimitive.content == "i2r") {
                    assertArrayEquals("$name i2r", cipher, sess.send.encrypt(plain))
                } else {
                    assertArrayEquals("$name r2i", plain, sess.recv.decrypt(cipher))
                }
            }
        }
    }

    @Test fun rejectsWrongResponderKeyAndTampering() {
        val o = vectors[0].jsonObject
        fun f(k: String) = hex(o[k]!!.jsonPrimitive.content)
        val s = Noise.KeyPair(f("initStaticPriv"), Noise.publicFromPrivate(f("initStaticPriv")))
        val e = Noise.KeyPair(f("initEphemeralPriv"), Noise.publicFromPrivate(f("initEphemeralPriv")))
        // A different expected host key: msg2 from the real host must not verify.
        val impostor = Noise.generateKeyPair().publicKey
        val ini = Noise.Initiator(s, impostor, f("prologue"), null, ephemeral = e)
        ini.writeMessage1(f("msg1Payload"))
        try {
            ini.readMessage2(f("msg2")); fail("accepted a response for the wrong host key")
        } catch (_: Exception) {
        }
        // A flipped bit in a transport frame must be rejected.
        val ok = Noise.Initiator(s, f("respStaticPub"), f("prologue"), null, ephemeral = e)
        ok.writeMessage1(f("msg1Payload"))
        val sess = ok.readMessage2(f("msg2"))
        val r2i = o["transport"]!!.jsonArray.map { it.jsonObject }.first { it["dir"]!!.jsonPrimitive.content == "r2i" }
        val bad = hex(r2i["cipher"]!!.jsonPrimitive.content).also { it[0] = (it[0].toInt() xor 1).toByte() }
        try {
            sess.recv.decrypt(bad); fail("accepted a tampered frame")
        } catch (_: Exception) {
        }
    }

    @Test fun keyGenerationAndUrls() {
        val a = Noise.generateKeyPair()
        val b = Noise.generateKeyPair()
        assertArrayEquals(Noise.dh(a.privateKey, b.publicKey), Noise.dh(b.privateKey, a.publicKey))
        assertEquals("wss://x.trycloudflare.com/v1/ws?m=pair&p=AB-c", SecureSocket.wsUrl("https://x.trycloudflare.com/", "pair", "AB-c"))
        assertEquals("ws://127.0.0.1:9473/v1/ws?m=conn", SecureSocket.wsUrl("http://127.0.0.1:9473", "conn", null))
        assertTrue(SecureSocket.closeReason(1008, "unpaired").contains("isn't paired"))
    }
}
